def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(x, default=(0, 0)):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return default

    def best_step_to(target, sx, sy):
        tx, ty = pos(target, (sx, sy))
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def nearest(items, sx, sy):
        best_item = None
        best_d = None
        for item in items or []:
            if not isinstance(item, (list, tuple)) or len(item) < 2:
                continue
            d = abs(item[0] - sx) + abs(item[1] - sy)
            if best_d is None or d < best_d:
                best_d = d
                best_item = item
        return best_item

    env = observation.get("environment_name", "")
    self_pos = pos(observation.get("self_position"), (0, 0))
    opp_pos = pos(observation.get("opponent_position"), (0, 0))
    sx, sy = self_pos
    ox, oy = opp_pos
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return best_step_to((ox, oy), sx, sy)
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = None
        best_d = None
        for c in corners:
            d = abs(c[0] - ox) + abs(c[1] - oy)
            if best_d is None or d > best_d:
                best_d = d
                target = c
        return best_step_to(target, sx, sy)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells")
        if not targets:
            targets = observation.get("opponent_territory")
        if not targets:
            targets = observation.get("frontier_cells")
        target = nearest(targets, sx, sy)
        if target is not None:
            return best_step_to(target, sx, sy)
        # fallback: move toward opponent or center
        if ox != 0 or oy != 0:
            return best_step_to((ox, oy), sx, sy)
        return best_step_to((gw // 2, gh // 2), sx, sy)

    resources = observation.get("resources") or observation.get("resource_cells") or []
    target = nearest(resources, sx, sy)
    if target is not None:
        return best_step_to(target, sx, sy)

    # Generic fallback: chase opponent if nearby, else move to center
    if abs(ox - sx) + abs(oy - sy) > 0:
        return best_step_to((ox, oy), sx, sy)
    return best_step_to((gw // 2, gh // 2), sx, sy)

